<script setup>
import { computed,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import StatusTag from '../components/StatusTag.vue';import { TASK_STATUS,assignTaskLeader,getSelectedStudents,getTaskById } from '../mock/tasks.js'
const route=useRoute();const router=useRouter();const advisorId='T001';const allowed=[TASK_STATUS.PUBLISHED,TASK_STATUS.SELECTING,TASK_STATUS.SELECTED,TASK_STATUS.LEADER_ASSIGNED,TASK_STATUS.IN_PROGRESS];const task=computed(()=>{const item=getTaskById(route.params.id);return item?.advisorId===advisorId&&allowed.includes(item.status)?item:null});const students=computed(()=>task.value?getSelectedStudents(task.value.taskId):[]);const leaderId=ref(task.value?.leaderId||'');if(students.value.length===1)leaderId.value=students.value[0].studentId;function save(){if(!students.value.length)return window.alert('请先筛选学生后再指定队长。');if(!leaderId.value)return window.alert('必须指定 1 名队长。');const result=assignTaskLeader(task.value.taskId,leaderId.value);window.alert(result.message);if(result.success)router.push(`/teacher/tasks/${task.value.taskId}/applicants`)}function back(){router.push(`/teacher/tasks/${route.params.id}/applicants`)}
</script>
<template><main class="page"><div class="content"><template v-if="task"><header><div><p class="eyebrow">T105 · ASSIGN LEADER</p><h1>指定队长</h1><p>{{ task.title }}</p></div><StatusTag :status="task.status" /></header><section v-if="!students.length" class="warning">请先筛选学生后再指定队长。</section><section class="card"><h2>当前队长状态</h2><dl><div><dt>已选中学生</dt><dd>{{ students.length }} 人</dd></div><div><dt>当前队长</dt><dd>{{ task.leaderName||'尚未指定' }}</dd></div></dl><p v-if="students.length===1" class="hint">仅有 1 名学生参与，系统已自动选择该学生为队长，请保存确认。</p></section><section class="card"><h2>从已选中学生中指定队长</h2><div class="students"><label v-for="student in students" :key="student.studentId"><input v-model="leaderId" type="radio" :value="student.studentId" /><span><strong>{{ student.studentName }}</strong><small>{{ student.studentId }} · {{ student.college||'--' }} · {{ student.major||'--' }}</small></span><StatusTag v-if="task.leaderId===student.studentId" status="confirmed" text="当前队长" /></label><p v-if="!students.length" class="empty">暂无已选中学生，请先完成学生筛选。</p></div></section><div class="actions"><button class="back" @click="back">返回</button><button class="save" :disabled="!students.length" @click="save">保存队长信息</button></div></template><section v-else class="card empty">无权访问或当前任务状态不支持指定队长。</section></div></main></template>
<style scoped>.page{min-height:100vh;padding:40px 24px;background:#f3f6fb}.content{width:min(100%,860px);margin:auto}header{display:flex;justify-content:space-between;gap:20px;margin-bottom:20px}h1{margin:0}header p{color:#64748b}.eyebrow{margin:0 0 6px;color:#2563eb!important;font-size:12px;font-weight:800;letter-spacing:.12em}.warning{margin-bottom:18px;padding:15px;border-radius:10px;color:#92400e;background:#fef3c7}.card{margin-bottom:18px;padding:22px;border:1px solid #e2e8f0;border-radius:14px;background:#fff}.card h2{margin:0 0 18px}dl{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin:0}dt{color:#64748b;font-size:13px}dd{margin:5px 0 0;font-weight:700}.hint{margin:18px 0 0;padding:12px;border-radius:9px;color:#1d4ed8;background:#eff6ff}.students{display:grid;gap:10px}.students label{display:flex;align-items:center;gap:14px;padding:15px;border:1px solid #e2e8f0;border-radius:10px;cursor:pointer}.students input{width:18px;height:18px;accent-color:#2563eb}.students span{flex:1}.students small{display:block;margin-top:5px;color:#64748b}.empty{text-align:center;color:#64748b}.actions{display:flex;justify-content:flex-end;gap:10px}.actions button{padding:10px 18px;border-radius:9px;font:inherit;font-weight:700;cursor:pointer}.back{border:1px solid #cbd5e1;background:#fff}.save{border:0;color:#fff;background:#2563eb}.save:disabled{opacity:.5}@media(max-width:650px){.page{padding:24px 14px}header{flex-direction:column}dl{grid-template-columns:1fr}.students label{align-items:flex-start;flex-wrap:wrap}}</style>
